PLAIN_SP = """You write a text again for a learner, in ASD-STE100 Simplified Technical English, at a US grade 9 reading level.
- Keep the meaning and every fact. Keep every number, every $...$ maths span and every `code` span exactly as it is.
- Use short sentences of at most 20 words, the active voice and common words. Do not use semicolons.
- Name each technical thing by its real name, and say in plain words what it is the first time. Never make up a nickname or a metaphor for it.
- A question first says the setup in plain sentences: what is fixed and what changes. Then it asks one thing.
- Do not add facts. Do not answer a question that the text asks."""

def plain_prompt(x, why) -> str:
    "The prompt that asks the model to write `x` (a text, or a dict of texts) again; `why` has the problems (of each key, for a dict)."
    if isinstance(x, str): return f"Write this text again.\n\nThe text:\n{x}\n\nIts problems:\n" + '\n'.join(f'- {w}' for w in why) + '\n\nReply with the new text only.'
    return (f"Write these texts again.\n\nThe texts, as JSON:\n{json.dumps(x, ensure_ascii=False)}\n\nThe problems of each text:\n"
            + '\n'.join(f'- {k}: {w}' for k, ws in why.items() for w in ws) + '\n\nReturn JSON with the same keys and no other keys.')

# %% ../nbs/03_agent.ipynb #f3df6e36
_SPAN = re.compile(r'```.*?```|`[^`\n]*`|\$\$.*?\$\$|\$[^$\n]+\$', re.S)
_NUM = re.compile(r'(?<![\w.])\d+(?:[.,]\d+)*')

def keeps(old:str, new:str, keep=()) -> bool:
    "Whether `new` has each maths span, code span, number and `keep` text of `old`."
    return (all(x in new for x in [*_SPAN.findall(old), *(k for k in keep if k in old)])
            and set(_NUM.findall(_SPAN.sub(' ', old))) <= set(_NUM.findall(_SPAN.sub(' ', new))))

# %% ../nbs/03_agent.ipynb #439e3aa9
def _better(old:str, new, terms=(), keep=()) -> bool:
    "Whether the text `new` is a plainer `old` that keeps its maths, code, numbers and `keep` texts."
    if not isinstance(new, str) or not (new := new.strip()) or (new[0] in '{[' and old.strip()[:1] not in '{['): return False
    if not len(old) / 3 <= len(new) <= 3 * len(old) + 80: return False   # a plain text can be longer: it says the setup
    return keeps(old, new, keep) and len(plain_why(new, terms)) < len(plain_why(old, terms))

def plain(ask, x, terms=(), keep=()):
    "`x` (a text, or a dict of texts) in plain English: each text that fails `plain_why` is written again by `ask` in one call, and kept only when it is better."
    if isinstance(x, str):
        if not (why := plain_why(x, terms)): return x
        try: new = ask(plain_prompt(x, why), PLAIN_SP)
        except Exception: return x
        return new.strip() if _better(x, new, terms, keep) else x
    why = {k: w for k, v in x.items() if isinstance(v, str) and (w := plain_why(v, terms))}
    if not why: return x
    try: r = parse_json(ask(plain_prompt({k: x[k] for k in why}, why), PLAIN_SP))
    except Exception: return x
    return type(x)({**x, **{k: r[k].strip() for k in why if _better(x[k], r.get(k), terms, keep)}})
